import { describe, expect, it } from "vitest";
import { parseTaskRuntimeSnapshot } from "@hodor/admin/mobile/async-task/runtime/domain.js";
import phoneWire from "../test/fixtures/mobile-task-runtime-wire.json";

// Generated by the phone's actual buildTaskStateSnapshot using synthetic tasks only.
describe("mobile-task-runtime phone wire contract", () => {
  it.each(Object.entries(phoneWire))(
    "accepts the phone's exact %s payload without dropping fields",
    (_phase, payload) => {
      const parsed = parseTaskRuntimeSnapshot(payload);
      expect(JSON.stringify(parsed)).toBe(JSON.stringify(payload));
      expect(parsed.deviceId).toBe("fixture-device");
    }
  );
});
